import React from 'react';
import { useLocation } from 'react-router-dom';
import { FF_MAX_CHARS_IN_DESCRIPTION } from 'constants/form-field';
import * as THUMBNAIL_STATUSES from 'constants/thumbnail_upload_statuses';
import { COLLECTION_PAGE } from 'constants/urlParams';
import * as TAGS from 'constants/tags';
import { FormField, FormUrlName } from 'component/common/form';
import { FormContext } from 'component/common/form-components/form';
import TagsSelect from 'component/tagsSelect';
import Card from 'component/common/card';
import ChannelSelector from 'component/channelSelector';
import CollectionPublishAdditionalOptions from './internal/additionalOptions';
import { lazyImport } from 'util/lazyImport';
import { useAppSelector } from 'redux/hooks';
import { selectHasClaimForId, selectNameForClaimId } from 'redux/selectors/claims';
import './style.scss';
const SelectThumbnail = lazyImport(
  () =>
    import(
      'component/selectThumbnail'
      /* webpackChunkName: "selectThumbnail" */
    )
);
const TAGS_LIMIT = 5;
type Props = {
  collectionId: string;
  formParams: any;
  setThumbnailError: (error: string | null | undefined) => void;
  updateFormParams: (obj: any) => void;
};

function CollectionGeneralTab(props: Props) {
  const { collectionId, formParams, setThumbnailError, updateFormParams } = props;
  const { channel_id: collectionChannelId, name, title, description, thumbnail_url: thumbnailUrl, tags } = formParams;
  const hasClaim = useAppSelector((state) => selectHasClaimForId(state, collectionId));
  const collectionChannelName = useAppSelector((state) => selectNameForClaimId(state, collectionChannelId));
  const { updateFormErrors } = React.useContext(FormContext);
  const { search } = useLocation();
  const urlParams = new URLSearchParams(search);
  const publishing = urlParams.get(COLLECTION_PAGE.QUERIES.VIEW) === COLLECTION_PAGE.VIEWS.PUBLISH;
  const [thumbStatus, setThumbStatus] = React.useState<string | undefined>();
  const [thumbError, setThumbError] = React.useState<string | undefined>();

  function handleUpdateThumbnail(update: Record<string, string>) {
    const { thumbnail_url: url, thumbnail_status: status, thumbnail_error: error } = update;

    if (url?.length >= 0) {
      const newParams =
        url.length === 0
          ? {
              thumbnail_url: undefined,
            }
          : update;
      updateFormParams(
        !publishing
          ? {
              thumbnail_url: newParams.thumbnail_url,
            }
          : newParams
      );
      setThumbStatus(undefined);
      setThumbError(undefined);
    } else {
      if (status) {
        setThumbStatus(status);
      } else {
        setThumbError(error);
      }
    }
  }

  React.useEffect(() => {
    const thumbnailError =
      thumbError && thumbStatus !== THUMBNAIL_STATUSES.COMPLETE
        ? __('Invalid thumbnail')
        : thumbStatus === THUMBNAIL_STATUSES.IN_PROGRESS
          ? __('Please wait for thumbnail to finish uploading')
          : undefined;
    setThumbnailError(thumbnailError);
    updateFormErrors('thumbnail', thumbnailError); // eslint-disable-next-line react-hooks/exhaustive-deps -- ignore updateFormErrors
  }, [setThumbnailError, thumbError, thumbStatus]);
  return (
    <div className="card card--background collection-edit__wrapper">
      {publishing && (
        <>
          <ChannelSelector
            autoSet
            channelToSet={collectionChannelId}
            onChannelSelect={(id) =>
              updateFormParams({
                channel_id: id,
              })
            }
          />

          <div className="collection__name-wrapper">
            <h2>{__('Name')}</h2>
            <div className="collection__name">
              <FormUrlName
                channelName={collectionChannelName}
                name={name}
                {...({
                  autoFocus: !hasClaim,
                  disabled: hasClaim,
                  onChange: (e: any) => updateFormParams({ name: e.target.value || '' }),
                } as any)}
              />

              <span className="form-field__help">
                {!hasClaim
                  ? __("This won't be able to be changed in the future.")
                  : __('This field cannot be changed.')}
              </span>
            </div>
          </div>
        </>
      )}

      <div className="collection__title">
        <h2>{__('Title')}</h2>
        <FormField
          type="text"
          name="collection_title"
          placeholder={__('My Awesome Playlist')}
          value={title || ''}
          onChange={(e) =>
            updateFormParams({
              title: e.target.value || '',
            })
          }
        />
      </div>

      <fieldset-section>
        <SelectThumbnail
          {...({
            thumbnailParam: thumbnailUrl,
            thumbnailParamError: thumbError,
            thumbnailParamStatus: thumbStatus,
            updateThumbnailParams: handleUpdateThumbnail,
            optional: true,
          } as any)}
        />
      </fieldset-section>

      <h2>{__('Description')}</h2>
      <FormField
        type="markdown"
        name="collection_description"
        value={(typeof description === 'string' && description) || ''}
        onChange={(value) =>
          updateFormParams({
            description: value || '',
          })
        }
        textAreaMaxLength={FF_MAX_CHARS_IN_DESCRIPTION}
      />

      <h2
        className="card__title"
        style={{
          marginTop: 'var(--spacing-l)',
        }}
      >
        {__('Tags')}
      </h2>
      <Card
        background
        body={
          <div className="publish-row">
            <TagsSelect
              suggestMature={false}
              disableAutoFocus
              hideHeader
              label={__('Selected Tags')}
              empty={__('No tags added')}
              excludedControlTags={
                [
                  TAGS.DISABLE_COMMENTS_TAG,
                  TAGS.DISABLE_DOWNLOAD_BUTTON_TAG,
                  TAGS.DISABLE_REACTIONS_COMMENTS_TAG,
                  TAGS.DISABLE_SLIMES_COMMENTS_TAG,
                ] as any
              }
              limitSelect={TAGS_LIMIT}
              help={__(
                "Add tags that are relevant to your content so those who're looking for it can find it more easily. If your content is best suited for mature audiences, ensure it is tagged 'mature'."
              )}
              placeholder={__('gaming, crypto')}
              onSelect={(newTags) => {
                const validatedTags = [];
                newTags.forEach((newTag) => {
                  if (!tags.some((tag) => tag.name === newTag.name)) {
                    validatedTags.push(newTag);
                  }
                });
                updateFormParams({
                  tags: [...tags, ...validatedTags],
                });
              }}
              onRemove={(clickedTag) => {
                const newTags = tags.slice().filter((tag) => tag.name !== clickedTag.name);
                updateFormParams({
                  tags: newTags,
                });
              }}
              tagsChosen={tags}
            />
          </div>
        }
      />

      {publishing && (
        <fieldset-section>
          <CollectionPublishAdditionalOptions />
        </fieldset-section>
      )}
    </div>
  );
}

export default CollectionGeneralTab;
